package com.lqq.supportflow.conversation.api;
import com.lqq.supportflow.conversation.application.CreateConversationService; import com.lqq.supportflow.conversation.domain.Conversation; import com.lqq.supportflow.shared.AuthenticatedPrincipal; import java.net.URI; import org.springframework.http.ResponseEntity; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/customer/conversations") public class CreateConversationController { private final CreateConversationService service; public CreateConversationController(CreateConversationService service){this.service=service;} @PostMapping ResponseEntity<Conversation> create(@AuthenticationPrincipal AuthenticatedPrincipal principal){Conversation conversation=service.create(principal.tenantId(),principal.userId());return ResponseEntity.created(URI.create("/api/v1/customer/conversations/"+conversation.id())).body(conversation);}}
